-- Generated from reviewed daily devotional content. Do not edit by hand.
with rows as (
  select * from jsonb_to_recordset($daily$[{"content_version":1,"id":"day-1","rotation_order":1,"status":"published","theme":"pureza"},{"content_version":1,"id":"day-2","rotation_order":2,"status":"published","theme":"fortaleza"},{"content_version":1,"id":"day-3","rotation_order":3,"status":"published","theme":"gracia"},{"content_version":1,"id":"day-4","rotation_order":4,"status":"published","theme":"identidad"},{"content_version":1,"id":"day-5","rotation_order":5,"status":"published","theme":"comunidad"},{"content_version":1,"id":"day-6","rotation_order":6,"status":"published","theme":"verdad"},{"content_version":1,"id":"day-7","rotation_order":7,"status":"published","theme":"esperanza"}]$daily$::jsonb) as x(
    id text, theme text, status text, rotation_order integer, content_version integer
  )
)
insert into public.daily_devotionals (id, theme, status, rotation_order, content_version, published_at)
select id, theme, status, rotation_order, content_version, timezone('utc', now()) from rows
on conflict (id) do update set
  theme = excluded.theme,
  status = excluded.status,
  rotation_order = excluded.rotation_order,
  content_version = excluded.content_version,
  published_at = coalesce(public.daily_devotionals.published_at, excluded.published_at),
  updated_at = timezone('utc', now());

with rows as (
  select * from jsonb_to_recordset($daily$[{"devotional_id":"day-1","locale":"es","practice":"Antes de abrir una app que suele tentarte, respira, ora una frase breve y vuelve al refugio.","prayer":"Senor Jesus, ayudame a cuidar mi interior sin vivir en condenacion. Ordena mis deseos y ensename a escoger lo que da vida.","question":"Que puerta pequena necesitas cerrar hoy para cuidar tu corazon?","reference":"Proverbios 4:23","reflection":"La pureza empieza mucho antes de una pantalla. Empieza en lo que dejas entrar al corazon: pensamientos, conversaciones, cansancio, soledad y deseos que no fueron llevados a Dios. Guardar el corazon no es vivir con miedo; es aprender a reconocer que tu vida interior vale demasiado para dejarla sin cuidado. Jesus no te llama a una vigilancia fria, sino a una libertad despierta. Hoy puedes cerrar una puerta pequena antes de que se vuelva una cadena grande.","title":"Guarda el corazon","verse":"Sobre toda cosa guardada, guarda tu corazon; porque de el mana la vida."},{"devotional_id":"day-2","locale":"es","practice":"Define ahora una acción de escape: dejar el teléfono lejos, caminar cinco minutos o escribir a alguien.","prayer":"Padre, dame humildad para no jugar con lo que me debilita. Cuando llegue la tentacion, ayudame a moverme rapido hacia ti.","question":"Cual sera tu primer movimiento cuando venga la tentacion?","reference":"1 Corintios 6:18","reflection":"Huir no es cobardia cuando el peligro quiere capturar tu alma. A veces la victoria mas espiritual es la mas practica: levantarte, cambiar de cuarto, dejar el celular, llamar a alguien o salir a caminar. La tentacion quiere que negocies en silencio; Dios te invita a moverte hacia la luz. No corras solo para alejarte del pecado. Corre hacia Cristo, hacia una amistad sana, hacia una decision concreta que proteja tu futuro.","title":"Huye hacia Dios","verse":"Huid de la fornicacion."},{"devotional_id":"day-3","locale":"es","practice":"Escribe una frase honesta: 'Senor, hoy necesito ayuda con...'. Luego ora esa frase en voz baja.","prayer":"Jesus, aqui estoy con verdad. No quiero esconderme. Recibo tu perdon y te pido fuerzas para caminar en luz.","question":"Que necesitas decirle a Dios sin maquillaje?","reference":"1 Juan 1:9","reflection":"La culpa suele decirte que te escondas hasta ser digno otra vez. El evangelio dice lo contrario: ven a la luz porque Cristo ya abrio el camino. Confesar no es firmar una derrota; es poner la verdad delante del Dios que restaura. Jesus no se sorprende por tu lucha. El no minimiza el pecado, pero tampoco reduce tu identidad a una caida. Hoy puedes hablar con honestidad y recibir perdon real.","title":"Limpios por gracia","verse":"Si confesamos nuestros pecados, el es fiel y justo para perdonar nuestros pecados."},{"devotional_id":"day-4","locale":"es","practice":"Memoriza una frase corta del versiculo de hoy y repitela cuando sientas ansiedad.","prayer":"Espiritu Santo, renueva mi mente. Cambia mis patrones y ensename a amar lo que me acerca a Dios.","question":"Que verdad vas a repetir cuando tu mente se desordene?","reference":"Romanos 12:2","reflection":"La mente aprende por repeticion. Si se alimenta de impulsos, termina pidiendo impulsos. Si se alimenta de verdad, empieza a reconocer otra hambre. Renovar la mente no es solo evitar contenido; es llenar el interior con Escritura, descanso, orden y comunidad. Dios no solo quiere controlar tu conducta, quiere sanar tu manera de desear. Cada pensamiento rendido a Cristo es una semilla de libertad.","title":"Renueva la mente","verse":"Transformaos por medio de la renovacion de vuestro entendimiento."},{"devotional_id":"day-5","locale":"es","practice":"Envia un mensaje simple a alguien confiable: 'Estoy cuidando mi pureza. Puedes orar por mi hoy?'.","prayer":"Senor, quita de mi el orgullo y la verguenza. Dame una comunidad sana y valor para caminar acompanado.","question":"A quien puedes pedirle apoyo esta semana?","reference":"Eclesiastes 4:9","reflection":"La adiccion digital crece en aislamiento, verguenza y secreto. La libertad, casi siempre, crece en compania. Dios usa personas para sostenernos: un amigo que pregunta, una comunidad que ora, alguien que no se escandaliza y aun asi te llama a algo mejor. Pedir ayuda no te hace debil; puede ser el acto mas valiente del dia. No fuiste creado para pelear solo.","title":"No caminas solo","verse":"Mejores son dos que uno."},{"devotional_id":"day-6","locale":"es","practice":"Haz una acción visible de cuidado: elimina un acceso, activa una capa o comparte tu decisión.","prayer":"Jesus, quiero vivir entero delante de ti. Sacame de lo escondido y ensename a amar la verdad.","question":"¿Qué acción visible puedes tomar hoy para caminar en luz?","reference":"Juan 3:21","reflection":"La oscuridad promete privacidad, pero termina quitando paz. Venir a la luz no significa exhibirte; significa dejar de vivir dividido. La luz de Cristo no humilla al que viene con arrepentimiento. La luz revela para sanar, no para destruir. Hoy puedes tomar una acción visible: activar protección, revisar tus patrones, pedir oración o cerrar una ruta de tentación. Un paso pequeño en la luz pesa más que mil promesas hechas en secreto.","title":"Ven a la luz","verse":"El que practica la verdad viene a la luz."},{"devotional_id":"day-7","locale":"es","practice":"Toma un minuto para agradecer una misericordia concreta de hoy antes de seguir.","prayer":"Padre, gracias porque tu fidelidad no se agota. Levantame con humildad y ayudame a caminar este dia contigo.","question":"Como puedes recibir la misericordia de Dios hoy?","reference":"Lamentaciones 3:23","reflection":"Tu progreso no depende de tener una semana perfecta, sino de volver a Dios con fe cada dia. La misericordia no es permiso para rendirse; es fuerza para levantarse sin mentira. Cuando caes, la verguenza quiere nombrarte por tu peor momento. Dios te llama por gracia y te invita a caminar otra vez. Hoy no empiezas desde cero: empiezas con un Padre fiel, una decision nueva y una historia que todavia esta siendo escrita.","title":"Misericordia nueva","verse":"Nuevas son cada manana; grande es tu fidelidad."},{"devotional_id":"day-1","locale":"en","practice":"Before opening an app that usually tempts you, breathe, pray a short phrase and return to the shelter.","prayer":"Lord Jesus, help me take care of my interior without living in condemnation. Order my desires and teach me to choose what gives life.","question":"What small door do you need to close today to take care of your heart?","reference":"Proverbios 4:23","reflection":"Purity begins long before a screen. It starts with what you let into your heart: thoughts, conversations, fatigue, loneliness and desires that were not brought to God. Guarding your heart is not living in fear; It is learning to recognize that your inner life is worth too much to leave without care. Jesus does not call you to cold vigilance, but to awakened freedom. Today you can close a small door before it becomes a big chain.","title":"Save the heart","verse":"Above all things guarded, guard your heart; because life flows from it."},{"devotional_id":"day-2","locale":"en","practice":"Now define an escape action: leave the phone away, walk for five minutes or write to someone.","prayer":"Father, give me humility so as not to play with what weakens me. When temptation comes, help me move quickly toward you.","question":"What will be your first move when temptation comes?","reference":"1 Corintios 6:18","reflection":"Fleeing is not cowardice when danger wants to capture your soul. Sometimes the most spiritual victory is the most practical: get up, change rooms, put down your cell phone, call someone or go for a walk. Temptation wants you to negotiate in silence; God invites you to move towards the light. Don't run just to get away from sin. Run towards Christ, towards a healthy friendship, towards a concrete decision that protects your future.","title":"Flee to God","verse":"Flee from fornication."},{"devotional_id":"day-3","locale":"en","practice":"Write an honest sentence: 'Lord, today I need help with...'. Then pray that phrase quietly.","prayer":"Jesus, here I am truly. I don't want to hide. I receive your forgiveness and ask you for strength to walk in the light.","question":"What do you need to say to God without makeup?","reference":"1 Juan 1:9","reflection":"Guilt often tells you to hide until you are worthy again. The gospel says the opposite: come to the light because Christ has already opened the way. Confessing is not signing a defeat; It is putting the truth before the God who restores. Jesus is not surprised by your struggle. He does not minimize sin, but neither does he reduce your identity to a fall. Today you can speak honestly and receive real forgiveness.","title":"Clean by grace","verse":"If we confess our sins, he is faithful and just to forgive our sins."},{"devotional_id":"day-4","locale":"en","practice":"Memorize a short phrase from today's verse and repeat it when you feel anxious.","prayer":"Holy Spirit, renew my mind. Change my patterns and teach me to love what brings me closer to God.","question":"What truth are you going to repeat when your mind becomes disordered?","reference":"Romanos 12:2","reflection":"The mind learns by repetition. If you feed on impulses, you end up asking for impulses. If you really eat, you begin to recognize another hunger. Renewing the mind is not just about avoiding content; It is to fill the interior with Scripture, rest, order and community. God not only wants to control your behavior, He wants to heal your way of desiring. Every thought surrendered to Christ is a seed of freedom.","title":"Renew the mind","verse":"Transform yourselves through the renewal of your understanding."},{"devotional_id":"day-5","locale":"en","practice":"Send a simple message to someone you trust: 'I'm taking care of my purity. Can you pray for me today?'","prayer":"Lord, take away my pride and shame. Give me a healthy community and courage to walk accompanied.","question":"Who can you ask for support this week?","reference":"Eclesiastes 4:9","reflection":"Digital addiction grows in isolation, shame and secrecy. Freedom, almost always, grows in company. God uses people to sustain us: a friend who asks, a community who prays, someone who is not scandalized and still calls you to something better. Asking for help doesn't make you weak; It may be the bravest act of the day. You were not created to fight alone.","title":"You don't walk alone","verse":"Two are better than one."},{"devotional_id":"day-6","locale":"en","practice":"Take a visible action of care: delete an access, activate a layer or share your decision.","prayer":"Jesus, I want to live whole before you. Take me out of the hidden and teach me to love the truth.","question":"What visible action can you take today to walk in light?","reference":"Juan 3:21","reflection":"Darkness promises privacy, but ends up taking away peace. Coming to the light does not mean showing off; It means stopping living divided. The light of Christ does not humble him who comes with repentance. Light reveals to heal, not to destroy. Today you can take visible action: activate protection, review your patterns, ask for prayer, or close a path of temptation. One small step into the light weighs more than a thousand promises made in secret.","title":"come to the light","verse":"He who practices the truth comes to the light."},{"devotional_id":"day-7","locale":"en","practice":"Take a minute to give thanks for a specific mercy today before continuing.","prayer":"Father, thank you that your faithfulness does not end. Lift me up with humility and help me walk this day with you.","question":"How can you receive God's mercy today?","reference":"Lamentaciones 3:23","reflection":"Your progress does not depend on having a perfect week, but on returning to God in faith each day. Mercy is not permission to give up; It is strength to rise without lies. When you fall, shame wants to name you by your worst moment. God calls you by grace and invites you to walk again. Today you don't start from scratch: you start with a faithful Father, a new decision and a story that is still being written.","title":"New mercy","verse":"They are new every morning; great is your faithfulness."},{"devotional_id":"day-1","locale":"fr","practice":"Avant d’ouvrir une application qui vous tente habituellement, respirez, priez une courte phrase et retournez au refuge.","prayer":"Seigneur Jésus, aide-moi à prendre soin de mon intérieur sans vivre dans la condamnation. Ordonne mes désirs et apprends-moi à choisir ce qui donne la vie.","question":"Quelle petite porte devez-vous fermer aujourd’hui pour prendre soin de votre cœur ?","reference":"Proverbios 4:23","reflection":"La pureté commence bien avant un écran. Cela commence par ce que vous laissez entrer dans votre cœur : les pensées, les conversations, la fatigue, la solitude et les désirs qui n'ont pas été portés à Dieu. Garder son cœur, ce n’est pas vivre dans la peur ; C’est apprendre à reconnaître que sa vie intérieure vaut trop pour la laisser sans souci. Jésus ne vous appelle pas à une froide vigilance, mais à une liberté éveillée. Aujourd’hui, on peut fermer une petite porte avant qu’elle ne devienne une grande chaîne.","title":"Sauver le coeur","verse":"Sur toutes choses gardées, gardez votre cœur ; parce que la vie en découle."},{"devotional_id":"day-2","locale":"fr","practice":"Définissez maintenant une action de fuite : laissez le téléphone à l'écart, marchez pendant cinq minutes ou écrivez à quelqu'un.","prayer":"Père, donne-moi de l'humilité pour ne pas jouer avec ce qui m'affaiblit. Quand la tentation vient, aide-moi à avancer rapidement vers toi.","question":"Quel sera votre premier geste lorsque la tentation surviendra ?","reference":"1 Corintios 6:18","reflection":"Fuir n’est pas une lâcheté lorsque le danger veut s’emparer de votre âme. Parfois, la victoire la plus spirituelle est la plus pratique : se lever, changer de chambre, poser son téléphone portable, appeler quelqu'un ou aller se promener. La tentation veut que vous négociiez en silence ; Dieu vous invite à avancer vers la lumière. Ne courez pas juste pour échapper au péché. Courez vers le Christ, vers une amitié saine, vers une décision concrète qui protège votre avenir.","title":"Fuyez vers Dieu","verse":"Fuyez la fornication."},{"devotional_id":"day-3","locale":"fr","practice":"Écrivez une phrase honnête : « Seigneur, aujourd’hui, j’ai besoin d’aide pour… ». Alors priez cette phrase tranquillement.","prayer":"Jesus, here I am truly. I don't want to hide. Je reçois votre pardon et vous demande la force de marcher dans la lumière.","question":"Que faut-il dire à Dieu sans se maquiller ?","reference":"1 Juan 1:9","reflection":"La culpabilité vous dit souvent de vous cacher jusqu'à ce que vous en soyez à nouveau digne. L’Évangile dit le contraire : venez à la lumière parce que le Christ a déjà ouvert la voie. Avouer, ce n’est pas signer une défaite ; C’est mettre la vérité devant le Dieu qui restaure. Jésus n'est pas surpris par votre lutte. Il ne minimise pas le péché, mais il ne réduit pas non plus votre identité à une chute. Aujourd’hui, vous pouvez parler honnêtement et recevoir un véritable pardon.","title":"Clean by grace","verse":"Si nous confessons nos péchés, il est fidèle et juste pour nous pardonner nos péchés."},{"devotional_id":"day-4","locale":"fr","practice":"Mémorisez une courte phrase du verset d’aujourd’hui et répétez-la lorsque vous vous sentez anxieux.","prayer":"Saint-Esprit, renouvelle mon esprit. Change mes schémas et apprends-moi à aimer ce qui me rapproche de Dieu.","question":"Quelle vérité allez-vous répéter lorsque votre esprit devient désordonné ?","reference":"Romanos 12:2","reflection":"L'esprit apprend par répétition. Si vous vous nourrissez d’impulsions, vous finissez par demander des impulsions. Si vous mangez vraiment, vous commencez à reconnaître une autre faim. Renouveler l’esprit ne consiste pas seulement à éviter le contenu ; C'est remplir l'intérieur d'Écriture, de repos, d'ordre et de communauté. Dieu ne veut pas seulement contrôler votre comportement, Il veut guérir votre façon de désirer. Chaque pensée abandonnée au Christ est une graine de liberté.","title":"Renouveler l'esprit","verse":"Transformez-vous par le renouvellement de votre compréhension."},{"devotional_id":"day-5","locale":"fr","practice":"Envoyez un message simple à quelqu'un en qui vous avez confiance : « Je prends soin de ma pureté. Pouvez-vous prier pour moi aujourd'hui ?","prayer":"Seigneur, enlève ma fierté et ma honte. Donnez-moi une communauté saine et le courage de marcher accompagné.","question":"À qui pouvez-vous demander de l’aide cette semaine ?","reference":"Eclesiastes 4:9","reflection":"La dépendance au numérique se développe dans l’isolement, la honte et le secret. La liberté, presque toujours, grandit en compagnie. Dieu utilise des personnes pour nous soutenir : un ami qui demande, une communauté qui prie, quelqu'un qui ne se scandalise pas et qui pourtant vous appelle à quelque chose de mieux. Demander de l'aide ne vous rend pas faible ; C’est peut-être l’acte le plus courageux de la journée. Vous n'avez pas été créé pour combattre seul.","title":"Tu ne marches pas seul","verse":"Deux valent mieux qu'un."},{"devotional_id":"day-6","locale":"fr","practice":"Effectuez une action de précaution visible : supprimez un accès, activez une couche ou partagez votre décision.","prayer":"Jésus, je veux vivre pleinement devant toi. Sortez-moi du caché et apprenez-moi à aimer la vérité.","question":"Quelle action visible pouvez-vous entreprendre aujourd’hui pour marcher dans la lumière ?","reference":"Juan 3:21","reflection":"L’obscurité promet l’intimité, mais finit par priver la paix. Venir à la lumière ne signifie pas se montrer ; Cela signifie arrêter de vivre divisé. La lumière du Christ n’humilie pas celui qui vient avec la repentance. La lumière révèle qu’elle guérit et non qu’elle détruit. Aujourd’hui, vous pouvez prendre des mesures visibles : activer la protection, revoir vos habitudes, demander la prière ou fermer un chemin de tentation. Un petit pas vers la lumière pèse plus que mille promesses faites en secret.","title":"viens à la lumière","verse":"Celui qui pratique la vérité apparaît à la lumière."},{"devotional_id":"day-7","locale":"fr","practice":"Prenez une minute pour remercier pour une miséricorde spécifique aujourd'hui avant de continuer.","prayer":"Père, merci car ta fidélité ne s'arrête pas. Relève-moi avec humilité et aide-moi à marcher cette journée avec toi.","question":"Comment pouvez-vous recevoir la miséricorde de Dieu aujourd’hui ?","reference":"Lamentaciones 3:23","reflection":"Votre progrès ne dépend pas d’une semaine parfaite, mais d’un retour à Dieu avec foi chaque jour. La miséricorde n'est pas la permission d'abandonner ; C'est la force de s'élever sans mensonge. Lorsque vous tombez, la honte veut vous nommer votre pire moment. Dieu vous appelle par grâce et vous invite à marcher à nouveau. Aujourd'hui, on ne part pas de zéro : on commence avec un Père fidèle, une nouvelle décision et une histoire qui est encore en train de s'écrire.","title":"Nouvelle miséricorde","verse":"Ils sont nouveaux chaque matin ; grande est ta fidélité."},{"devotional_id":"day-1","locale":"pt","practice":"Antes de abrir um aplicativo que costuma te tentar, respire, reze uma frase curta e volte para o abrigo.","prayer":"Senhor Jesus, ajuda-me a cuidar do meu interior sem viver na condenação. Ordene meus desejos e me ensine a escolher o que dá vida.","question":"Que portinha você precisa fechar hoje para cuidar do seu coração?","reference":"Proverbios 4:23","reflection":"A pureza começa muito antes de uma tela. Começa pelo que você deixou entrar no seu coração: pensamentos, conversas, cansaço, solidão e desejos que não foram levados a Deus. Guardar o seu coração não é viver com medo; É aprender a reconhecer que sua vida interior vale muito para ser deixada sem cuidados. Jesus não vos chama à fria vigilância, mas à liberdade desperta. Hoje você pode fechar uma pequena porta antes que ela se torne uma grande corrente.","title":"Salve o coração","verse":"Acima de todas as coisas guardadas, guarde o seu coração; porque a vida flui dele."},{"devotional_id":"day-2","locale":"pt","practice":"Agora defina uma ação de fuga: deixar o telefone longe, caminhar cinco minutos ou escrever para alguém.","prayer":"Pai, dá-me humildade para não brincar com o que me enfraquece. Quando a tentação chegar, ajude-me a avançar rapidamente em sua direção.","question":"Qual será o seu primeiro passo quando a tentação chegar?","reference":"1 Corintios 6:18","reflection":"Fugir não é covardia quando o perigo quer capturar sua alma. Às vezes a vitória mais espiritual é a mais prática: levantar, mudar de quarto, largar o celular, ligar para alguém ou dar um passeio. A tentação quer que você negocie em silêncio; Deus convida você a caminhar em direção à luz. Não corra só para fugir do pecado. Corra para Cristo, para uma amizade saudável, para uma decisão concreta que proteja o seu futuro.","title":"Fuja para Deus","verse":"Fuja da fornicação."},{"devotional_id":"day-3","locale":"pt","practice":"Escreva uma frase honesta: 'Senhor, hoje preciso de ajuda com...'. Então ore essa frase calmamente.","prayer":"Jesus, aqui estou eu de verdade. Eu não quero me esconder. Recebo seu perdão e lhe peço forças para caminhar na luz.","question":"O que você precisa dizer a Deus sem maquiagem?","reference":"1 Juan 1:9","reflection":"A culpa muitas vezes diz para você se esconder até que você seja digno novamente. O evangelho diz o contrário: venha para a luz porque Cristo já abriu o caminho. Confessar não é assinar uma derrota; É colocar a verdade diante do Deus que restaura. Jesus não se surpreende com a sua luta. Ele não minimiza o pecado, mas também não reduz a sua identidade a uma queda. Hoje você pode falar honestamente e receber perdão verdadeiro.","title":"Limpe pela graça","verse":"Se confessarmos os nossos pecados, ele é fiel e justo para perdoar os nossos pecados."},{"devotional_id":"day-4","locale":"pt","practice":"Memorize uma frase curta do versículo de hoje e repita-a quando se sentir ansioso.","prayer":"Espírito Santo, renove minha mente. Mude meus padrões e me ensine a amar o que me aproxima de Deus.","question":"Que verdade você repetirá quando sua mente ficar desordenada?","reference":"Romanos 12:2","reflection":"A mente aprende por repetição. Se você se alimenta de impulsos, acaba pedindo impulsos. Se você realmente come, começa a reconhecer outra fome. Renovar a mente não significa apenas evitar conteúdos; É preencher o interior com Escritura, descanso, ordem e comunidade. Deus não quer apenas controlar o seu comportamento, Ele quer curar a sua maneira de desejar. Cada pensamento entregue a Cristo é uma semente de liberdade.","title":"Renove a mente","verse":"Transformem-se através da renovação da sua compreensão."},{"devotional_id":"day-5","locale":"pt","practice":"Envie uma mensagem simples para alguém em quem você confia: ‘Estou cuidando da minha pureza. Você pode orar por mim hoje?'","prayer":"Senhor, tire meu orgulho e vergonha. Dai-me uma comunidade saudável e coragem para caminhar acompanhado.","question":"A quem você pode pedir apoio esta semana?","reference":"Eclesiastes 4:9","reflection":"O vício digital cresce no isolamento, na vergonha e no sigilo. A liberdade, quase sempre, cresce em companhia. Deus usa pessoas para nos sustentar: um amigo que pede, uma comunidade que reza, alguém que não se escandaliza e ainda te chama para algo melhor. Pedir ajuda não o torna fraco; Pode ser o ato mais corajoso do dia. Você não foi criado para lutar sozinho.","title":"Você não anda sozinho","verse":"Dois são melhores que um."},{"devotional_id":"day-6","locale":"pt","practice":"Tome uma atitude visível de cuidado: exclua um acesso, ative uma camada ou compartilhe sua decisão.","prayer":"Jesus, quero viver inteiro diante de ti. Tire-me do oculto e ensine-me a amar a verdade.","question":"Que ação visível você pode realizar hoje para andar na luz?","reference":"Juan 3:21","reflection":"A escuridão promete privacidade, mas acaba tirando a paz. Vir para a luz não significa exibir-se; Significa parar de viver dividido. A luz de Cristo não humilha quem vem com arrependimento. A luz revela para curar, não para destruir. Hoje você pode tomar medidas visíveis: ativar a proteção, rever seus padrões, pedir oração ou fechar o caminho da tentação. Um pequeno passo em direção à luz pesa mais do que mil promessas feitas em segredo.","title":"venha para a luz","verse":"Quem pratica a verdade vem para a luz."},{"devotional_id":"day-7","locale":"pt","practice":"Reserve um minuto para agradecer por uma misericórdia específica hoje antes de continuar.","prayer":"Pai, obrigado porque sua fidelidade não acaba. Levante-me com humildade e ajude-me a caminhar este dia com você.","question":"Como você pode receber a misericórdia de Deus hoje?","reference":"Lamentaciones 3:23","reflection":"Seu progresso não depende de ter uma semana perfeita, mas de retornar a Deus com fé todos os dias. Misericórdia não é permissão para desistir; É força para subir sem mentiras. Quando você cai, a vergonha quer te nomear pelo seu pior momento. Deus te chama pela graça e te convida a caminhar novamente. Hoje você não começa do zero: você começa com um Pai fiel, uma nova decisão e uma história que ainda está sendo escrita.","title":"Nova misericórdia","verse":"Eles são novos todas as manhãs; grande é a sua fidelidade."}]$daily$::jsonb) as x(
    devotional_id text, locale text, title text, verse text, reference text,
    reflection text, question text, prayer text, practice text
  )
)
insert into public.daily_devotional_translations (
  devotional_id, locale, title, verse, reference, reflection, question, prayer, practice
)
select devotional_id, locale, title, verse, reference, reflection, question, prayer, practice from rows
on conflict (devotional_id, locale) do update set
  title = excluded.title,
  verse = excluded.verse,
  reference = excluded.reference,
  reflection = excluded.reflection,
